statement:
You are given three integers `k`, `digit1` and `digit2`. Find the smallest integer that meets all three rules:

- it is strictly greater than `k`;
- it is divisible by `k`;
- each digit of its usual decimal form (no leading zeros) equals `digit1` or `digit2` (using only one of the two is fine).

Return that integer. If no integer meets the rules, or the smallest one is larger than `2^31 - 1` (the biggest signed 32-bit value), return `-1`.

validator:
function validate([k, digit1, digit2]) {
  if (!Number.isInteger(k) || k < 1 || k > 1000) return 'k is an integer from 1 to 1000.';
  if (!Number.isInteger(digit1) || digit1 < 0 || digit1 > 9) return 'digit1 is a single digit from 0 to 9.';
  if (!Number.isInteger(digit2) || digit2 < 0 || digit2 > 9) return 'digit2 is a single digit from 0 to 9.';
  return null;
}

reference:
function findInteger(k, digit1, digit2) {
  const digits = digit1 === digit2 ? [digit1] : [Math.min(digit1, digit2), Math.max(digit1, digit2)];
  const limit = 2 ** 31 - 1;
  const queue = digits.filter((digit) => digit > 0);

  for (let head = 0; head < queue.length; head++) {
    const value = queue[head];
    if (value > k && value % k === 0) {
      return value;
    }
    for (const digit of digits) {
      const next = value * 10 + digit;
      if (next <= limit) {
        queue.push(next);
      }
    }
  }
  return -1;
}

brute:
function findInteger(k, digit1, digit2) {
  let best = -1;
  for (let length = 1; length <= 10; length++) {
    for (let mask = 0; mask < (1 << length); mask++) {
      let text = '';
      for (let bit = 0; bit < length; bit++) text += (mask >> bit) & 1 ? digit2 : digit1;
      const value = Number(text);
      if (value > k && value % k === 0 && value <= 2147483647 && (best === -1 || value < best)) best = value;
    }
  }
  return best;
}

